function build(n) { if (built[n] || !$("phdItem" + n)) return; built[n] = true; ({ 1: item1, 2: item2, 3: item3, 4: item4, 5: item5, 6: item6 })[n](); }

/* ------------------------------------------------------------------ small SVG line chart (series colour via CSS class) */
function lineChart({ series, xs, ymax, ylabel, xlabel = "Month", yticks, height = 300 }) {
  const W = 760, H = height, L = 56, Rr = 190, T = 14, B = 42, pw = W - L - Rr, ph = H - T - B;
  const X = (x) => L + (x - xs[0]) / (xs[xs.length - 1] - xs[0]) * pw, Y = (y) => T + ph - Math.min(y, ymax) / ymax * ph;
  const ticks = yticks || [0, 0.25, 0.5, 0.75, 1].map((p) => p * ymax);
  let s = `<svg class="phd-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(ylabel)}">`;
  ticks.forEach((t) => { s += `<line class="phd-grid" x1="${L}" x2="${L + pw}" y1="${Y(t)}" y2="${Y(t)}"/><text class="phd-tick" x="${L - 6}" y="${Y(t) + 4}" text-anchor="end">${t}</text>`; });
  xs.forEach((x) => { s += `<text class="phd-tick" x="${X(x)}" y="${T + ph + 16}" text-anchor="middle">${x}</text>`; });
  s += `<text class="phd-axis" x="${L + pw / 2}" y="${H - 6}" text-anchor="middle">${esc(xlabel)}</text>`;
  s += `<text class="phd-axis" x="14" y="${T + ph / 2}" text-anchor="middle" transform="rotate(-90 14 ${T + ph / 2})">${esc(ylabel)}</text>`;
  const ends = [];
  series.forEach((se, i) => {
    const c = se.c != null ? se.c : i + 1;     // colour follows the entity (se.c), not the position
    const pts = se.y.map((y, j) => [se.x ? se.x[j] : xs[j], y]).filter((p) => p[1] != null);
    if (!pts.length) return;
    s += `<path class="phd-s${c}" fill="none" stroke-width="2"${c === 0 ? ' stroke-dasharray="5 3"' : ""} d="${pts.map((p, j) => (j ? "L" : "M") + X(p[0]).toFixed(1) + "," + Y(p[1]).toFixed(1)).join(" ")}"/>`;
    pts.forEach((p) => { s += `<circle class="phd-f${c}" cx="${X(p[0]).toFixed(1)}" cy="${Y(p[1]).toFixed(1)}" r="3.5"><title>${esc(se.name)} – ${xlabel} ${p[0]}: ${f(p[1], 2)}</title></circle>`; });
    ends.push([Y(pts[pts.length - 1][1]), se.name, c]);
  });
  ends.sort((a, b) => a[0] - b[0]); for (let j = 1; j < ends.length; j++) if (ends[j][0] - ends[j - 1][0] < 15) ends[j][0] = ends[j - 1][0] + 15;
  ends.forEach(([y, n, i]) => { s += `<circle class="phd-f${i}" cx="${L + pw + 12}" cy="${y}" r="5"/><text class="phd-leg" x="${L + pw + 22}" y="${y + 4}">${esc(n)}</text>`; });
  return s + "</svg>";
}

