const EX = {
  fail: { label: "Failures – Gamma–Poisson (Eq. 4.5)", a: { prior: 30, worth: 300, n: 14, T: 310 }, note: "Example 4.1 – HMC: design MTBF 30 h worth 300 h; month 1: 14 failures in 310 h uptime." },
  rep: { label: "Repair time – Gamma–exponential (Eq. 4.7)", a: { prior: 20, worth: 5, list: "12 35 28 41 19 55 23 30 26 38 17 44 31 22" }, note: "Example 4.2 – HMC: design MTTR 20 min worth 5 repairs; 14 repairs observed (minutes)." },
  cyc: { label: "Cycle time – Normal-Inverse-Gamma on ln t (Eq. 4.9)", a: { prior: 345, spread: 10, worth: 10, mean: 371, sd: 5, n: 40 }, note: "Example 4.3 – HMC VC20: supplier 345 s ± 10 % worth 10 cycles; 40 measured cycles, mean 371 s, sd 5 %." },
  scr: { label: "Scrap rate – Beta–binomial (Eq. 4.10)", a: { prior: 0.8, worth: 250, x: 9, n: 400 }, note: "Example 4.4 – HMC: design scrap 0.8 % worth 250 parts; 9 scrap in 400 parts." },
};
let bayesKind = "fail";
function item2() {
  $("phdItem2").innerHTML = `
  <div class="card"><div class="card-head"><h2>Static capacity and bottleneck – Eq. 4.1–4.2</h2><span class="sub">change any value; design estimates from Table 4.2 ${LBL("design")} – replace with your supplier data</span></div>
    <p class="phd-eq">A = MTBF / (MTBF + MTTR) &nbsp;·&nbsp; C<sub>m</sub> = c<sub>m</sub> · A<sub>m</sub> · 3600 · H / (t̄<sub>m</sub> + h<sub>m</sub>) · (1 − q<sub>m</sub>) &nbsp;·&nbsp; t̄<sub>m</sub> = Σ π<sub>p</sub> t<sub>pm</sub></p>
    <div class="phd-row"><label>Productive hours per month H <input type="number" id="phdH" value="330" min="50" max="720" step="10"></label>
      <label>Mix VC10 / VC20 / VC30 <input type="number" id="phdM1" value="0.3" step="0.05" min="0" max="1"> <input type="number" id="phdM2" value="0.5" step="0.05" min="0" max="1"> <input type="number" id="phdM3" value="0.2" step="0.05" min="0" max="1"></label>
      <button class="btn" id="phdCapReset">Reset to design</button></div>
    <div class="phd-scroll"><table class="wi" id="phdCapTbl"></table></div>
    <div id="phdCapBars"></div></div>
  <div class="card"><div class="card-head"><h2>Bayesian updating of one parameter – Eq. 4.4–4.11</h2><span class="sub">design statement + its worth → prior; shop-floor data → posterior; 90 % interval by 40 000 samples</span></div>
    <div class="mx-nav" role="group" aria-label="model">${Object.entries(EX).map(([k, e]) => `<button class="mx-el${k === bayesKind ? " active" : ""}" data-phdbk="${k}">${esc(e.label)}</button>`).join("")}</div>
    <div id="phdBayes"></div></div>`;
  const cap = $("phdCapTbl");
  const fill = () => {
    cap.innerHTML = `<thead><tr><th>Station</th><th>c</th><th>t VC10 [s]</th><th>t VC20 [s]</th><th>t VC30 [s]</th><th>h [s]</th><th>MTBF [h]</th><th>MTTR [min]</th><th>scrap q</th><th>A</th><th>C [parts/month]</th></tr></thead><tbody>${C.STATIONS.map((s, i) => `<tr data-i="${i}"><td><b>${s.name}</b></td>${[["c", s.c, 1], ["t0", s.t.VC10, 1], ["t1", s.t.VC20, 1], ["t2", s.t.VC30, 1], ["h", s.h, 1], ["mtbf", s.mtbf, 1], ["mttr", s.mttr, 1], ["q", s.q, 0.001]].map(([k, v, st]) => `<td><input type="number" data-k="${k}" value="${v}" step="${st}" min="0"></td>`).join("")}<td class="phd-A"></td><td class="phd-C"></td></tr>`).join("")}</tbody>`;
    calc();
  };
  const calc = () => {
    const H = +$("phdH").value, mix = { VC10: +$("phdM1").value, VC20: +$("phdM2").value, VC30: +$("phdM3").value };
    const sm = mix.VC10 + mix.VC20 + mix.VC30 || 1; Object.keys(mix).forEach((k) => { mix[k] /= sm; });
    const res = [...cap.querySelectorAll("tbody tr")].map((tr) => {
      const g = (k) => +tr.querySelector(`[data-k="${k}"]`).value;
      const st = { c: g("c"), t: { VC10: g("t0"), VC20: g("t1"), VC30: g("t2") }, h: g("h"), mtbf: g("mtbf"), mttr: g("mttr"), q: g("q") };
      const r = C.capacity(st, mix, H); tr.querySelector(".phd-A").textContent = f(r.A, 4); tr.querySelector(".phd-C").textContent = f(r.C, 0);
      return { name: tr.cells[0].textContent, C: r.C, tr };
    });
    const minC = Math.min(...res.map((r) => r.C)); const sorted = [...res].sort((a, b) => a.C - b.C);
    res.forEach((r) => r.tr.classList.toggle("phd-bn", r.C === minC));
    const maxC = Math.max(...res.map((r) => r.C));
    $("phdCapBars").innerHTML = `<p class="phd-res">Bottleneck: <b>${sorted[0].name}</b> with <b>${f(sorted[0].C, 0)}</b> parts/month ${LBL("calculated")} · next: ${sorted[1].name} ${f(sorted[1].C, 0)} (+${f(100 * (sorted[1].C / sorted[0].C - 1), 1)} %), ${sorted[2].name} ${f(sorted[2].C, 0)} (+${f(100 * (sorted[2].C / sorted[0].C - 1), 1)} %). Static capacity is optimistic – blocking, starvation and failures in the DES (item 3) lower it.</p>
      <div class="phd-bars">${res.map((r) => `<div class="phd-bar${r.C === minC ? " phd-bnbar" : ""}"><span>${r.name}</span><i style="width:${(100 * r.C / maxC).toFixed(1)}%"></i><em>${f(r.C, 0)}</em></div>`).join("")}</div>`;
  };
  cap.addEventListener("input", calc); ["phdH", "phdM1", "phdM2", "phdM3"].forEach((id) => $(id).addEventListener("input", calc));
  $("phdCapReset").addEventListener("click", () => { $("phdH").value = 330; $("phdM1").value = 0.3; $("phdM2").value = 0.5; $("phdM3").value = 0.2; fill(); });
  fill();
  $("phdItem2").querySelectorAll("[data-phdbk]").forEach((b) => b.addEventListener("click", () => { bayesKind = b.dataset.phdbk; $("phdItem2").querySelectorAll("[data-phdbk]").forEach((x) => x.classList.toggle("active", x === b)); bayesForm(); }));
  bayesForm();
}
function bayesForm() {
  const e = EX[bayesKind], a = e.a, inp = (id, lab, v, st = "any") => `<label>${lab} <input type="number" id="phdB_${id}" value="${v}" step="${st}"></label>`;
  let fields = "";
  if (bayesKind === "fail") fields = inp("prior", "Design MTBF [h]", a.prior) + inp("worth", "worth [equivalent hours]", a.worth) + inp("n", "observed failures n", a.n, 1) + inp("T", "in uptime T [h]", a.T) + inp("rho", "forgetting ρ", 1, 0.05);
  if (bayesKind === "rep") fields = inp("prior", "Design MTTR [min]", a.prior) + inp("worth", "worth [repairs]", a.worth) + `<label>observed repair times [min], separated by spaces <input type="text" id="phdB_list" value="${a.list}" style="width:320px"></label>`;
  if (bayesKind === "cyc") fields = inp("prior", "Supplier cycle time [s]", a.prior) + inp("spread", "± spread covering 90 % [%]", a.spread) + inp("worth", "worth [cycles]", a.worth) + inp("mean", "measured mean [s]", a.mean) + inp("sd", "measured sd [%]", a.sd) + inp("n", "number measured n", a.n, 1);
  if (bayesKind === "scr") fields = inp("prior", "Design scrap [%]", a.prior) + inp("worth", "worth [parts]", a.worth) + inp("x", "scrap parts x", a.x, 1) + inp("n", "of parts n", a.n, 1);
  $("phdBayes").innerHTML = `<p class="sub">${esc(e.note)} ${LBL("design")} prior · observations ${LBL("simulated")} – replace with your data</p><div class="phd-row">${fields}</div><div id="phdBres"></div>`;
  $("phdBayes").querySelectorAll("input").forEach((x) => x.addEventListener("input", bayesCalc)); bayesCalc();
}
function bayesCalc() {
  const g = (id) => +$("phdB_" + id).value, R = C.rng(7), N = 40000;
  let prior, post, unit, rows = [];
  try {
    if (bayesKind === "fail") {
      const m = new C.FailureRate(g("prior"), g("worth")); const p0 = Array.from({ length: N }, () => m.sampleMtbf(R)); const pr = { a: m.a, b: m.b, mean: m.mtbfMean() };
      m.update(g("n"), g("T"), g("rho") || 1); const p1 = Array.from({ length: N }, () => m.sampleMtbf(R));
      prior = { s: p0, mean: pr.mean, txt: `Gamma(${f(pr.a, 2)}, ${f(pr.b, 1)})` }; post = { s: p1, mean: m.mtbfMean(), txt: `Gamma(${f(m.a, 2)}, ${f(m.b, 1)})` }; unit = "MTBF [h]";
      rows = [["a ← ρa + n", f(m.a, 2)], ["b ← ρb + T", f(m.b, 1)], ["E[MTBF] = b / (a − 1)", f(m.mtbfMean(), 2) + " h"]];
    } else if (bayesKind === "rep") {
      const list = $("phdB_list").value.split(/[\s,;]+/).map(Number).filter((x) => x > 0);
      const m = new C.RepairTime(g("prior") / 60, g("worth")); const p0 = Array.from({ length: N }, () => 60 * m.sampleMttr(R)); const pa = m.a, pb = m.b, pm = 60 * m.mttrMean();
      m.update(list.map((x) => x / 60)); const p1 = Array.from({ length: N }, () => 60 * m.sampleMttr(R));
      prior = { s: p0, mean: pm, txt: `Gamma(${f(pa, 1)}, ${f(pb * 60, 0)} min)` }; post = { s: p1, mean: 60 * m.mttrMean(), txt: `Gamma(${f(m.a, 1)}, ${f(m.b * 60, 0)} min)` }; unit = "MTTR [min]";
      rows = [["k repairs", list.length], ["mean of data", f(C.mean(list), 1) + " min"], ["E[MTTR] = b / (a − 1)", f(60 * m.mttrMean(), 2) + " min"]];
    } else if (bayesKind === "cyc") {
      const m = new C.CycleTime(g("prior"), g("spread") / 100, g("worth")); const samp = () => { const s2 = 1 / R.gamma(m.a, 1 / m.b), mm = R.gauss(m.m, Math.sqrt(s2 / m.k)); return Math.exp(mm + s2 / 2); };
      const p0 = Array.from({ length: N }, samp), pm = m.meanTime(), pk = m.k;
      const Rd = C.rng(43), data = Array.from({ length: Math.max(1, Math.round(g("n"))) }, () => Math.exp(Rd.gauss(Math.log(g("mean")), g("sd") / 100)));
      m.update(data); const p1 = Array.from({ length: N }, samp);
      prior = { s: p0, mean: pm, txt: `NIG(m ${f(Math.log(g("prior")), 3)}…, κ ${f(pk, 0)})` }; post = { s: p1, mean: m.meanTime(), txt: `NIG(m ${f(m.m, 4)}, κ ${f(m.k, 0)}, a ${f(m.a, 1)}, b ${f(m.b, 4)})` }; unit = "mean cycle time [s]";
      rows = [["κ_n = κ₀ + n", f(m.k, 0)], ["weight of data n / κ_n", f(100 * data.length / m.k, 0) + " %"], ["mean of generated data", f(C.mean(data), 1) + " s"], ["posterior E[t]", f(m.meanTime(), 1) + " s"]];
    } else {
      const m = new C.ScrapRate(g("prior") / 100, g("worth")); const p0 = Array.from({ length: N }, () => 100 * m.sample(R)); const pm = 100 * m.mean(), pa = m.a, pb = m.b;
      m.update(g("x"), g("n")); const p1 = Array.from({ length: N }, () => 100 * m.sample(R));
      prior = { s: p0, mean: pm, txt: `Beta(${f(pa, 1)}, ${f(pb, 1)})` }; post = { s: p1, mean: 100 * m.mean(), txt: `Beta(${f(m.a, 1)}, ${f(m.b, 1)})` }; unit = "scrap rate [%]";
      rows = [["a + x", f(m.a, 1)], ["b + n − x", f(m.b, 1)], ["E[q] = (a + x) / (a + b + n)", f(100 * m.mean(), 2) + " %"]];
    }
  } catch (err) { $("phdBres").innerHTML = `<p class="am-warn">Check the inputs: ${esc(err.message)}</p>`; return; }
  const i0 = C.interval(prior.s), i1 = C.interval(post.s);
  $("phdBres").innerHTML = `<div class="grid2 eq" style="margin-top:6px"><div>${density(prior.s, post.s, unit)}</div><div>
    <table><thead><tr><th></th><th>Prior (design)</th><th>Posterior (with data)</th></tr></thead><tbody>
      <tr><td>Distribution</td><td>${prior.txt}</td><td>${post.txt}</td></tr>
      <tr><td>Mean ${esc(unit)}</td><td>${f(prior.mean, 2)}</td><td><b>${f(post.mean, 2)}</b></td></tr>
      <tr><td>90 % interval</td><td>${f(i0[0], 2)} – ${f(i0[1], 2)}</td><td><b>${f(i1[0], 2)} – ${f(i1[1], 2)}</b></td></tr>
      <tr><td>Interval width</td><td>${f(i0[1] - i0[0], 2)}</td><td>${f(i1[1] - i1[0], 2)} (${f(100 * (1 - (i1[1] - i1[0]) / (i0[1] - i0[0])), 0)} % narrower)</td></tr></tbody></table>
    <table style="margin-top:8px"><tbody>${rows.map(([a, b]) => `<tr><td>${esc(a)}</td><td><b>${b}</b></td></tr>`).join("")}</tbody></table>
    <p class="sub">The interval shrinks = epistemic uncertainty (lack of knowledge) removed by data. Only this part can be reduced – the natural variation (aleatory) stays.</p></div></div>`;
}
function density(a, b, unit) {
  const all = [...a, ...b].sort((x, y) => x - y), lo = all[Math.floor(0.005 * all.length)], hi = all[Math.floor(0.995 * all.length)], nb = 50, w = (hi - lo) / nb || 1;
  const hist = (s) => { const h = new Array(nb).fill(0); s.forEach((v) => { const k = Math.floor((v - lo) / w); if (k >= 0 && k < nb) h[k]++; }); return h.map((c) => c / s.length / w); };
  const ha = hist(a), hb = hist(b), ym = Math.max(...ha, ...hb), Wd = 640, Hh = 240, L = 10, B = 34, X = (k) => L + k / nb * (Wd - 2 * L), Y = (v) => Hh - B - v / ym * (Hh - B - 10);
  const path = (h) => "M" + X(0) + "," + Y(0) + h.map((v, k) => `L${X(k).toFixed(1)},${Y(v).toFixed(1)}L${X(k + 1).toFixed(1)},${Y(v).toFixed(1)}`).join("") + `L${X(nb)},${Y(0)}`;
  return `<svg class="phd-chart" viewBox="0 0 ${Wd} ${Hh}"><path class="phd-area1" d="${path(ha)}"/><path class="phd-area2" d="${path(hb)}"/>
    <line class="phd-grid" x1="${L}" x2="${Wd - L}" y1="${Y(0)}" y2="${Y(0)}"/>
    ${[0, 0.25, 0.5, 0.75, 1].map((p) => `<text class="phd-tick" x="${X(p * nb)}" y="${Hh - 12}" text-anchor="middle">${f(lo + p * (hi - lo), 1)}</text>`).join("")}
    <text class="phd-axis" x="${Wd / 2}" y="${Hh - 0}" text-anchor="middle">${esc(unit)}</text>
    <circle class="phd-f1" cx="${Wd - 160}" cy="14" r="5"/><text class="phd-leg" x="${Wd - 150}" y="18">prior (design)</text>
    <circle class="phd-f2" cx="${Wd - 160}" cy="32" r="5"/><text class="phd-leg" x="${Wd - 150}" y="36">posterior (with data)</text></svg>`;
}

