function runLab() {
  const seed = Math.max(1, Math.round(+$("phdSeed").value || 1)), w = +$("phdLw").value, it = C.rampupScenario(seed, { nTheta: 20, w });
  const rows = []; $("phdRun").disabled = true; $("phdRunMsg").textContent = " simulating month 1 …";
  const step = () => {
    const r = it.next(); if (r.done) { $("phdRun").disabled = false; $("phdRunMsg").textContent = " done."; return; }
    rows.push(r.value); render(rows); $("phdRunMsg").textContent = r.value.k < 12 ? ` simulating month ${r.value.k + 1} …` : " done.";
    if (r.value.k < 12) setTimeout(step, 10); else $("phdRun").disabled = false;
  };
  setTimeout(step, 10);
}
function render(rows) {
  const xs = Array.from({ length: 12 }, (_, i) => i + 1), ym = Math.ceil(Math.max(...rows.map((r) => Math.max(r.y, r.B0.m, r.P07D.hi))) / 500) * 500;
  const pick = (k) => xs.map((x) => { const r = rows.find((q) => q.k === x); return r ? k(r) : null; });
  $("phdLabChart").innerHTML = lineChart({ xs, ymax: ym, yticks: [0, 0.25, 0.5, 0.75, 1].map((p) => Math.round(p * ym)), ylabel: "Good output per month [parts]",
    series: [{ name: "truth (hidden factory)", c: 0, y: pick((r) => r.y) }, { name: "B0 design model", c: 1, y: pick((r) => r.B0.m) }, { name: "P07 Bayesian twin", c: 3, y: pick((r) => r.P07.m) }, { name: "P07D twin + discrepancy", c: 4, y: pick((r) => r.P07D.m) }] });
  const e = (p, y) => f(100 * Math.abs(p - y) / y, 1) + " %";
  $("phdLabTbl").innerHTML = `<thead><tr><th>Month</th><th>Truth</th><th>B0 (err)</th><th>P07 (err)</th><th>P07D [90 % PI] (err)</th><th>True / twin / design bottleneck</th></tr></thead><tbody>${rows.map((r) => `<tr><td>${r.k}</td><td><b>${f(r.y, 0)}</b></td><td>${f(r.B0.m, 0)} (${e(r.B0.m, r.y)})</td><td>${f(r.P07.m, 0)} (${e(r.P07.m, r.y)})</td><td>${f(r.P07D.m, 0)} [${f(r.P07D.lo, 0)}–${f(r.P07D.hi, 0)}] (${e(r.P07D.m, r.y)})${r.y >= r.P07D.lo && r.y <= r.P07D.hi ? " ✓" : " ✗"}</td><td>${r.bnTrue} / <span class="${r.bnBay === r.bnTrue ? "phd-ok" : "phd-no"}">${r.bnBay}</span> / <span class="${r.bnDes === r.bnTrue ? "phd-ok" : "phd-no"}">${r.bnDes}</span></td></tr>`).join("")}</tbody>`;
}

