function commCalc() {
  const g = (id) => +$("phdC_" + id).value;
  const N = g("N"), P = g("P"), k = Math.max(1, g("k")), n = g("n"), rtt = C.rttMean(g("tnet"), g("t0"), g("scan")), rttMax = g("tnet") + g("t0") + g("scan");
  const bytes = C.pollBytes(n), bw = N * k * bytes * 8 / P / 1e6;
  const tSeq = N * k * rtt, tPar = k * (rttMax + N * g("gw")), nMax = C.nMaxSeq(P, k, rtt);
  const lam = 1 / (g("pulse") / 100 * (g("pmin") + g("pmax")) / 2 + (1 - g("pulse") / 100) * g("ms"));
  const out = (mode, tc) => { const Pe = Math.max(P, tc / 1000); return { Pe, latM: Pe / 2 + rtt / 1000, latX: Pe + rttMax / 1000, miss: C.stateOnlyMiss(Pe, g("pulse") / 100, g("pmin"), g("pmax"), g("ms")), ring: C.poissonTail(lam * Pe, Math.round(g("ring"))), ts: Pe / Math.sqrt(12) }; };
  const s = out("seq", tSeq), p = out("par", tPar), ok = (x) => (x ? '<span class="phd-ok">✓</span>' : '<span class="phd-no">✗</span>');
  const h1 = (o) => N >= 40 && o.latX <= 1 && o.ring <= 0.001;
  $("phdCres").innerHTML = `<div class="phd-kpis">
      <div class="phd-kpi"><b>${bytes}</b><span>bytes on the wire per poll (Eq. 5.1)</span></div>
      <div class="phd-kpi"><b>${f(bw, 2)}</b><span>Mbit/s = ${f(100 * bw / g("link"), 2)} % of the link</span></div>
      <div class="phd-kpi"><b>${f(rtt, 2)} ms</b><span>mean round trip (Eq. 5.3)</span></div>
      <div class="phd-kpi"><b>${f(nMax, 0)}</b><span>machines max. for a sequential gateway at this P (Eq. 5.4)</span></div></div>
    <table><thead><tr><th></th><th>Sequential gateway</th><th>Parallel gateway</th></tr></thead><tbody>
      <tr><td>Cycle time for N machines</td><td>${f(tSeq, 1)} ms ${tSeq / 1000 > P ? '<span class="phd-no">longer than P – period cannot be held</span>' : ""}</td><td>${f(tPar, 1)} ms</td></tr>
      <tr><td>Effective period P<sub>eff</sub></td><td>${f(s.Pe, 3)} s</td><td>${f(p.Pe, 3)} s</td></tr>
      <tr><td>Detection latency mean / max (Eq. 5.5)</td><td>${f(s.latM, 3)} / ${f(s.latX, 3)} s</td><td>${f(p.latM, 3)} / ${f(p.latX, 3)} s</td></tr>
      <tr><td>State-only polling: share of state segments never seen</td><td>${f(100 * s.miss, 1)} %</td><td>${f(100 * p.miss, 1)} %</td></tr>
      <tr><td>Event block: loss probability per interval (Eq. 5.6, λ = ${f(lam, 3)}/s)</td><td>${s.ring.toExponential(2)}</td><td>${p.ring.toExponential(2)}</td></tr>
      <tr><td>Time-stamp error sd, state-only (P<sub>eff</sub>/√12)</td><td>${f(s.ts, 3)} s</td><td>${f(p.ts, 3)} s</td></tr>
      <tr><td><b>H1</b>: N ≥ 40, max latency ≤ 1 s, loss ≤ 0.1 % (with event block)</td><td>${ok(h1(s))}</td><td>${ok(h1(p))}</td></tr></tbody></table>
    <p class="sub">With the event block the PLC time stamp replaces the poll time, so its error is the PLC scan time plus the clock offset (synchronised hourly by the gateway).</p>`;
}

